using System;
using System.IO;
using System.Linq;
using Unity.FPS.Game;
using Unity.FPS.Gameplay;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEditor.TestTools.TestRunner.Api;
using UnityEngine;
using UnityEngine.SceneManagement;
using Object=UnityEngine.Object;
namespace IronRequiem.Editor
{
    [InitializeOnLoad]public static class AnimationRestoreAuthoring
    {
        const string Queue="Tools/IronRequiem/Requests/animation-restore.txt",Key="IRON.AnimationRestore",Reports="Tools/IronRequiem/Reports/AnimationRestore",Projectile="Assets/IronRequiem/Prefabs/Weapons/Projectile_IR_Integrated_v05.prefab";static readonly DateTime LoadedAt=DateTime.UtcNow;static TestRunnerApi api;
        static AnimationRestoreAuthoring(){EditorApplication.update+=Tick;if(SessionState.GetBool(Key+".testing",false))EditorApplication.delayCall+=Register;}
        static bool Dirty()=>Enumerable.Range(0,SceneManager.sceneCount).Any(i=>SceneManager.GetSceneAt(i).isDirty);
        static void Register(){if(!api){api=ScriptableObject.CreateInstance<TestRunnerApi>();api.RegisterCallbacks(new Results());}}
        static void Tick(){if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode||SessionState.GetBool(Key+".testing",false))return;if(SessionState.GetBool(Key+".restore",false)&&EditorApplication.timeSinceStartup-SessionState.GetFloat(Key+".at",0)>3){SessionState.EraseBool(Key+".restore");if(!Dirty())EditorSceneManager.OpenScene(HitWeaponAuthoring.Lab);}if(!File.Exists(Queue))return;foreach(var path in new[]{"Assets/IronRequiem/Editor/AnimationRestoreAuthoring.cs","Assets/IronRequiem/Tests/PlayMode/AnimationRestoreTests.cs","Assets/IronRequiem/Scripts/Enemies/RobotHitFeedback.cs"})if(LoadedAt<File.GetLastWriteTimeUtc(path))return;var op=File.ReadAllText(Queue).Trim();File.Delete(Queue);Directory.CreateDirectory(Reports);try{if(op=="build"){Build();File.WriteAllText(Queue,"test");}else if(op=="test"){if(Dirty())throw new InvalidOperationException("Preserving dirty scene");Register();SessionState.SetBool(Key+".testing",true);api.Execute(new ExecutionSettings(new Filter{testMode=TestMode.PlayMode,testNames=new[]{"IronRequiem.Tests.AnimationRestoreTests"}}));}else if(op=="audit")IronRequiemSetupTools.WriteAudit();else throw new InvalidOperationException("Unknown restore action");}catch(Exception e){File.WriteAllText(Reports+"/error.txt",e.ToString());Debug.LogException(e);}}
        static void Build()
        {
            if(Dirty())throw new InvalidOperationException("Preserving dirty user scene");if(!File.Exists(Projectile)){var scene=EditorSceneManager.NewPreviewScene();try{var source=AssetDatabase.LoadAssetAtPath<GameObject>(PrimaryCapsulesAuthoring.Projectile);var instance=(GameObject)PrefabUtility.InstantiatePrefab(source,scene);instance.name="Projectile_IR_Integrated_v05";instance.GetComponent<ProjectileStandard>().Damage=6.5f;PrefabUtility.SaveAsPrefabAsset(instance,Projectile);}finally{EditorSceneManager.ClosePreviewScene(scene);}}
            var go=PrefabUtility.LoadPrefabContents(HitWeaponAuthoring.Weapon);try{var weapon=go.GetComponent<WeaponController>();weapon.ProjectilePrefab=AssetDatabase.LoadAssetAtPath<GameObject>(Projectile).GetComponent<ProjectileBase>();var cells=go.GetComponentsInChildren<Transform>(true).Where(t=>t.name.StartsWith("Capsule_")&&t.name.Length==9).OrderBy(t=>t.name).ToArray();if(cells.Length!=4)throw new InvalidOperationException("Expected original four cell views; preserve previous binding");var animated=new GameObject[4];for(int i=0;i<4;i++){var mount=new GameObject("AnimatedCapsuleSocket_"+(i+1)).transform;mount.SetParent(cells[i].parent,false);mount.localPosition=cells[i].localPosition;mount.localRotation=cells[i].localRotation;mount.localScale=cells[i].localScale;var view=Object.Instantiate(cells[i].gameObject,mount);view.name="AnimatedCapsule_"+(i+1);view.transform.localPosition=Vector3.zero;view.transform.localRotation=Quaternion.identity;view.transform.localScale=Vector3.one;animated[i]=view;cells[i].gameObject.SetActive(false);}
                var handler=go.GetComponent<WeaponFuelCellHandler>();if(!handler)throw new InvalidOperationException("Existing template fuel handler is required");handler.FuelCells=animated;handler.SimultaneousFuelCellsUsage=false;handler.FuelCellUsedPosition=new Vector3(0,.1f,0);handler.FuelCellUnusedPosition=Vector3.zero;PrefabUtility.SaveAsPrefabAsset(go,HitWeaponAuthoring.Weapon);
            }finally{PrefabUtility.UnloadPrefabContents(go);}
            var reference=PrefabUtility.LoadPrefabContents("Assets/FPS/Prefabs/Enemies/Enemy_HoverBot.prefab");AnimationCurve curve;float duration;try{var clip=AssetDatabase.LoadAllAssetsAtPath(AssetDatabase.GUIDToAssetPath("d4c6e776733ed444c81b0b76a8610f82")).OfType<AnimationClip>().First(c=>!c.name.StartsWith("__preview"));var animator=reference.GetComponentInChildren<Animator>();var transforms=animator.GetComponentsInChildren<Transform>(true);clip.SampleAnimation(animator.gameObject,0);var positions=transforms.Select(t=>t.localPosition).ToArray();var rotations=transforms.Select(t=>t.localRotation).ToArray();var values=new float[17];for(int i=0;i<values.Length;i++){clip.SampleAnimation(animator.gameObject,clip.length*i/16);for(int j=0;j<transforms.Length;j++)values[i]=Mathf.Max(values[i],Quaternion.Angle(rotations[j],transforms[j].localRotation)/10+Vector3.Distance(positions[j],transforms[j].localPosition)*transforms[j].lossyScale.x*40);}float peak=values.Max();if(peak<.001f)throw new InvalidOperationException("No actual hurt motion in template reference");var keys=values.Select((v,i)=>new Keyframe(i/16f,i==0||i==16?0:v/peak)).ToArray();curve=new AnimationCurve(keys);for(int i=0;i<curve.length;i++)curve.SmoothTangents(i,0);duration=Mathf.Clamp(clip.length,.18f,.24f);File.WriteAllText(Reports+"/reference.txt","Template hurt clip="+clip.name+" duration="+clip.length+" measured pose peak="+peak+"; mapped envelope to native torso, duration="+duration+"; bounded overlapping reactions per impact, no NavMesh/root displacement");}finally{PrefabUtility.UnloadPrefabContents(reference);}
            foreach(var path in new[]{HitWeaponAuthoring.Big,HitWeaponAuthoring.T07}){go=PrefabUtility.LoadPrefabContents(path);try{go.GetComponent<RobotHitFeedback>().ConfigurePerImpact(curve,duration,7);PrefabUtility.SaveAsPrefabAsset(go,path);}finally{PrefabUtility.UnloadPrefabContents(go);}}AssetDatabase.SaveAssets();
        }
        sealed class Results:IErrorCallbacks{public void RunStarted(ITestAdaptor t){}public void TestStarted(ITestAdaptor t){}public void TestFinished(ITestResultAdaptor t){}public void OnError(string m){SessionState.EraseBool(Key+".testing");File.WriteAllText(Reports+"/runner-error.txt",m);}public void RunFinished(ITestResultAdaptor r){if(!SessionState.GetBool(Key+".testing",false))return;SessionState.EraseBool(Key+".testing");TestRunnerApi.SaveResultToFile(r,Reports+"/play.xml");File.WriteAllText(Reports+"/status.txt",r.ResultState+" passed="+r.PassCount+" failed="+r.FailCount);SessionState.SetBool(Key+".restore",true);SessionState.SetFloat(Key+".at",(float)EditorApplication.timeSinceStartup);}}
    }
}